// Bundles content/ into the app for offline play (CLAUDE.md §1.7): writes static requires for every
// content file and audio clip, since Metro can only bundle literal require() paths.
// Usage: pnpm build-packs          (write)
//        pnpm build-packs --check  (CI: fail if the generated file is stale)
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, relative, resolve } from "node:path";
import { loadContent } from "@kids-lang/content-schema/node";

const repo = resolve(import.meta.dirname, "..");
const contentRoot = join(repo, "content");
const outFile = join(repo, "apps/mobile/src/content/generated.ts");
const fromOut = (p: string) => relative(join(outFile, ".."), p).replaceAll("\\", "/");

const json = (dir: string) =>
  existsSync(join(contentRoot, dir))
    ? readdirSync(join(contentRoot, dir))
        .filter((f) => f.endsWith(".json"))
        .sort()
        .map((f) => join(contentRoot, dir, f))
    : [];
const req = (file: string) => `require("${fromOut(file)}")`;
const list = (files: string[]) => `[\n${files.map((f) => `    ${req(f)},`).join("\n")}\n  ]`;

const { bundle } = loadContent(contentRoot);
const audioRefs = new Set<string>();
for (const pack of bundle.packs) {
  if (!bundle.manifest.shippedPacks.includes(pack.lang)) continue;
  for (const lexeme of Object.values(pack.lexemes)) {
    for (const ref of Object.values(lexeme.audio)) if (ref) audioRefs.add(ref);
  }
}
for (const c of bundle.concepts) if (c.sfx) audioRefs.add(c.sfx);

const packs = bundle.manifest.shippedPacks.map((lang) =>
  join(contentRoot, "packs", lang, "pack.json"),
);
const source = `// GENERATED by \`pnpm build-packs\` from content/. Do not edit by hand.
/* eslint-disable @typescript-eslint/no-require-imports */

export const rawContent = {
  manifest: ${req(join(contentRoot, "manifest.json"))},
  concepts: ${list(json("concepts"))},
  units: ${list(json("curriculum/units"))},
  lessons: ${list(json("curriculum/lessons"))},
  profiles: ${list(json("curriculum/age-bands"))},
  packs: ${list(packs)},
};

/** Audio ref (content-root relative) → bundled asset. */
export const audioAssets: Record<string, number> = {
${[...audioRefs]
  .sort()
  .map((ref) => `  "${ref}": ${req(join(contentRoot, ref))},`)
  .join("\n")}
};
`;

if (process.argv.includes("--check")) {
  const current = existsSync(outFile) ? readFileSync(outFile, "utf8") : "";
  if (current !== source) {
    console.error(`✗ ${relative(repo, outFile)} is stale. Run \`pnpm build-packs\`.`);
    process.exit(1);
  }
  console.log("✓ Bundled content is up to date.");
} else {
  writeFileSync(outFile, source);
  console.log(`Wrote ${relative(repo, outFile)} (${audioRefs.size} audio clips).`);
}
